head.script:
scwin.screenId = "jldfil25710";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — jldfil25710: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25710.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_application
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_application = async function () {
    const sbmOptions = {
        id: "tx_fn_application",
        method: "post",
        action: "/account/advceComInfo.do",
        ref: "dma_applicationReq",
        target: "dlt_advceComInfoList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25710.tx_fn_application" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_delete
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/account/advceComInfo.do",
        ref: "dma_deleteReq",
        target: "dlt_advceComInfoList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25710.tx_fn_delete" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.application
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.application = async function () {
    /* sdd-asis-lifecycle:begin fn_application — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const str = "자문기업 추가/삭제 신청은\n[자문기업신청현황] 메뉴에서 신청가능합니다.\n 해당 메뉴로 이동하시겠습니까?";
    if (await $c.win.confirm(str)) {
        (document.advceComInfoForm || { elements: [] }).action = "/account/advceComInfo.do";
        $c.util.getComponent('dma_applicationReq').set('method', "advceComApplList");
        { const nr = await scwin.tx_fn_application(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil25720/jldfil25720.xml", { "method": "advceComApplList" }); } };
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteApplicationReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param advceComIsurCd comNm advceComApplTpCd
 * @returns
 * @hidden N
*/
scwin.deleteApplicationReq = async function (advceComIsurCd, comNm, advceComApplTpCd) {
    /* sdd-asis-lifecycle:begin fn_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.advceComInfoForm || { elements: [] }).action = "/account/advceComInfo.do";
    $c.util.getComponent('dma_applicationReq').set('method', "advceComInfoApply");
    $c.util.getComponent('dma_applicationReq').set('advceComIsurCd', advceComIsurCd);
    $c.util.getComponent('dma_applicationReq').set('advceComApplTpCd', advceComApplTpCd);
    const str = "『" + comNm + "』의 지정자문법인여부를 삭제요청하시겠습니까?";
    if (await $c.win.confirm(str)) {
        $c.util.getComponent('dma_applicationReq').set('applStat', "1");
        { const nr = await scwin.tx_fn_delete(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil25720/jldfil25720.xml", { "method": "advceComInfoApply", "advceComIsurCd": advceComIsurCd, "advceComApplTpCd": advceComApplTpCd, "applStat": "1" }); } };
    }
    /* sdd-asis-lifecycle:end */
};
